    select 'TECESCOLA','TECESCOLA_CORE_V4','TecEscola Core V4','CHEMISTRY','ATOMOS','massa','Em uma reacao fechada, a massa total permanece constante porque:','["A materia sai do recipiente.","Os atomos deixam de existir.","A massa depende apenas da cor.","Os atomos se reorganizam sem desaparecer."]'::jsonb,'"Os atomos se reorganizam sem desaparecer."'::jsonb,'A conservacao da massa decorre da reorganizacao das particulas.','HARD',4,'TECESCOLA_CORE_V3_REUSED','{"content_id":"v3-chemistry-chemistry_atoms-12","purpose":"REVIEW","context_family":"MASSA","cognitive_process":"EVALUATE","misconceptions":{"A materia sai do recipiente.":["MASS_CONSERVATION_DENIED"]},"primary_skill":"CHEMISTRY_STOICHIOMETRY","supporting_skills":[],"prerequisite_skills":[],"transfer_skills":[],"semantic_topic_owner":"CHEMISTRY_STOICHIOMETRY","content_authoring_status":"TECH_VALIDATED","pack_version":"tec-escola-core-v4","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING"}'::jsonb,true
